input.command:
cd /private/tmp/fta_2026-08-26/with/plan-gate__pg1/r2
SHIM=$(mktemp -d); export SHIM_LOG="$SHIM/calls.log"
# ---- fake psql: answers canned results based on the query text and which DSN it's pointed at
cat > "$SHIM/psql" <<'EOF'
#!/usr/bin/env bash
q=""; dsn=""
while (( $# )); do case "$1" in -c) q="$2"; shift;; --dbname=*) dsn="${1#--dbname=}";; esac; shift; done
side=source; [[ "$dsn" == *"/tgt"* ]] && side=target
printf '%s | %s\n' "$side" "$(printf '%s' "$q" | tr '\n' ' ' | tr -s ' ')" >> "$SHIM_LOG"
if [[ "${SHIM_FAIL_CONNECT:-}" == "$side" ]]; then echo "psql: connection refused" >&2; exit 2; fi
case "$q" in
  *"select version()"*)            echo "PostgreSQL 16.3 ($side)";;
  *"from pg_tables"*)              [[ $side == source ]] && echo 1 || echo 0;;
  *"from pg_namespace"*)           echo 1;;
  *"confrelid in (select oid from migrated)"*"conrelid not in"*) [[ -n "${SHIM_INBOUND_FK:-}" ]] && echo "invoices -> users (invoices_user_fk)" || true;;
  *"conrelid in (select oid from migrated)"*"confrelid not in"*) ;;
  *"pg_rewrite"*)                  echo "v public.user_orders_v";;
  *"pg_trigger"*)                  ;;
  *"format_type"*)                 ;;
  *"md5(string_agg"*"public.users"*)  echo "sum-users";;
  *"md5(string_agg"*"public.orders"*) [[ $side == target && -n "${SHIM_BAD_SUM:-}" ]] && echo "sum-orders-BAD" || echo "sum-orders";;
  *"count(*) from public.users"*)  echo 100;;
  *"count(*) from public.orders"*) [[ $side == target && -n "${SHIM_TGT_ORDERS:-}" ]] && echo "$SHIM_TGT_ORDERS" || echo 250;;
  *"pg_get_serial_sequence"*)      echo "public.users_id_seq";;
  *"last_value"*)                  echo 100;;
  *"drop table"*)                  ;;
  *) echo "psql shim: unhandled query: $q" >&2; exit 3;;
esac
EOF
cat > "$SHIM/pg_dump" <<'EOF'
#!/usr/bin/env bash
printf 'pg_dump | %s\n' "$*" >> "$SHIM_LOG"
for a in "$@"; do [[ "$a" == --file=* ]] && echo "fake dump" > "${a#--file=}"; done
EOF
cat > "$SHIM/pg_restore" <<'EOF'
#!/usr/bin/env bash
printf 'pg_restore | %s\n' "$*" >> "$SHIM_LOG"; exit 0
EOF
chmod +x "$SHIM"/psql "$SHIM"/pg_dump "$SHIM"/pg_restore
export PATH="$SHIM:$PATH" SOURCE_DSN='postgresql://u:secret@h/src' TARGET_DSN='postgresql://u:secret@h/tgt' DUMP_DIR="$SHIM/dumps"

scenario() { local name="$1"; shift; : > "$SHIM_LOG"; echo; echo "===== $name"; "$@"; echo "exit=$?"; }

scenario "A1 happy path (--checksum --drop-source --yes --keep-dump)" ./migrate.sh --checksum --drop-source --yes --keep-dump
echo "drop sent to: $(grep 'drop table' "$SHIM_LOG" | cut -d'|' -f1)"; echo "dumps: $(ls "$DUMP_DIR" | wc -l | tr -d ' ')"
scenario "A2 happy path again (repeat)" ./migrate.sh --checksum --drop-source --yes --keep-dump
scenario "A3 happy path under /bin/bash 3.2" /bin/bash ./migrate.sh --checksum --drop-source --yes
echo "dumps after default cleanup: $(ls "$DUMP_DIR" | wc -l | tr -d ' ')"
scenario "B target orders count mismatch" env SHIM_TGT_ORDERS=249 ./migrate.sh --drop-source --yes
echo "drop calls: $(grep -c 'drop table' "$SHIM_LOG")"
scenario "C checksum mismatch" env SHIM_BAD_SUM=1 ./migrate.sh --checksum --drop-source --yes
echo "drop calls: $(grep -c 'drop table' "$SHIM_LOG")"
scenario "D target connection refused" env SHIM_FAIL_CONNECT=target ./migrate.sh
echo "pg_dump calls: $(grep -c '^pg_dump' "$SHIM_LOG")"
scenario "E inbound FK blocks" env SHIM_INBOUND_FK=1 ./migrate.sh
scenario "E2 inbound FK overridden" env SHIM_INBOUND_FK=1 ./migrate.sh 2>&1 | grep -E 'WARNING|done'
scenario "F dry-run (redaction, no writes)" ./migrate.sh --dry-run --drop-source 2>&1 | grep -E 'DRY-RUN|secret'
echo "dump/restore real calls in dry-run: $(grep -cE '^(pg_dump|pg_restore)' "$SHIM_LOG")"
scenario "G drop confirmation with wrong input" bash -c 'echo nope | ./migrate.sh --drop-source' 2>&1 | tail -1
echo "drop calls: $(grep -c 'drop table' "$SHIM_LOG")"
scenario "H drop confirmation with correct input" bash -c 'echo "users orders" | ./migrate.sh --drop-source' 2>&1 | tail -3
